"use client"

import * as React from "react"
import { Calendar as CalendarIcon, ChevronLeft, ChevronRight } from "lucide-react"

import { useControllableState } from "../hooks"
import {
  buildMonthGrid,
  rotateWeekdayLabels,
  weekStartsOnForLocale,
} from "../lib/df-calendar-grid"
import {
  applyBoundedRangeClick,
  classifyDay,
  draftFromValue,
  formatUtcMonthLabel,
  isDayDisabled,
  moveCalendarFocus,
  resolveNearestEnabledDay,
  shiftUtcMonth,
  startOfUtcMonthIso,
  todayIsoDay,
  type DateRangeValue,
  type DayBounds,
  type RangeDraft,
} from "../lib/df-date-picker"
import {
  dfDatePickerWeekdays,
  useDfStrings,
  type DfStrings,
} from "../lib/df-intl"
import { cn } from "../lib/utils"
import { Input } from "./df-input"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "./df-popover"

type SharedPickerProps = {
  min?: string | null
  max?: string | null
  disabledDates?: (dayIso: string) => boolean
  placeholder?: string
  /** BCP 47 locale for month title and first day of week. */
  locale?: string
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  disabled?: boolean
  id?: string
  className?: string
  "aria-label"?: string
}

type DatePickerProps = SharedPickerProps & {
  value?: string | null
  defaultValue?: string | null
  onChange?: (value: string | null) => void
}

type DateRangePickerProps = SharedPickerProps & {
  value?: DateRangeValue | null
  defaultValue?: DateRangeValue | null
  onChange?: (value: DateRangeValue | null) => void
}

type CalendarPanelProps = {
  mode: "single" | "range"
  visibleMonth: string
  onVisibleMonthChange: (monthIso: string) => void
  focusIso: string
  onFocusIsoChange: (iso: string) => void
  value?: string | null | undefined
  draft?: RangeDraft | undefined
  hoverIso: string | null
  onHoverIsoChange: (iso: string | null) => void
  onSelectDay: (iso: string) => void
  min?: string | null | undefined
  max?: string | null | undefined
  disabledDates?: ((dayIso: string) => boolean) | undefined
  onRequestClose: () => void
  labelledBy?: string | undefined
  locale: string
  weekStartsOn: number
  weekdayLabels: readonly string[]
  strings: DfStrings
}

/** Format a closed range trigger value with catalogue word order. */
function formatRangeDisplay(
  value: DateRangeValue | null | undefined,
  strings: DfStrings
): string {
  if (value == null) return ""
  if (value.start === value.end) return value.start
  return strings.dateRangeDisplay({ start: value.start, end: value.end })
}

function CalendarPanel({
  mode,
  visibleMonth,
  onVisibleMonthChange,
  focusIso,
  onFocusIsoChange,
  value,
  draft,
  hoverIso,
  onHoverIsoChange,
  onSelectDay,
  min,
  max,
  disabledDates,
  onRequestClose,
  labelledBy,
  locale,
  weekStartsOn,
  weekdayLabels,
  strings,
}: CalendarPanelProps) {
  const gridId = React.useId()
  const today = todayIsoDay()
  const bounds = React.useMemo<DayBounds>(
    () => ({ min, max, disabledDates }),
    [disabledDates, max, min]
  )
  const cells = React.useMemo(
    () => buildMonthGrid(visibleMonth, weekStartsOn),
    [visibleMonth, weekStartsOn]
  )
  const monthLabel = formatUtcMonthLabel(visibleMonth, locale)

  React.useEffect(() => {
    const active = document.getElementById(`${gridId}-${focusIso}`)
    if (active == null || active.hasAttribute("disabled")) return
    active.focus()
  }, [focusIso, gridId, visibleMonth])

  function goMonth(delta: number) {
    onVisibleMonthChange(
      startOfUtcMonthIso(shiftUtcMonth(visibleMonth, delta))
    )
    const move = moveCalendarFocus(
      focusIso,
      delta < 0 ? "PageUp" : "PageDown",
      visibleMonth,
      weekStartsOn,
      bounds
    )
    if (move != null) onFocusIsoChange(move.focusIso)
  }

  function handleToday() {
    onVisibleMonthChange(startOfUtcMonthIso(today))
    const enabledToday = !isDayDisabled(today, bounds)
    if (enabledToday) {
      onFocusIsoChange(today)
      onSelectDay(today)
      return
    }
    onFocusIsoChange(
      resolveNearestEnabledDay(today, 1, bounds, {
        fallbackIso: resolveNearestEnabledDay(today, -1, bounds, {
          fallbackIso: focusIso,
        }),
      })
    )
  }

  function handleGridKeyDown(event: React.KeyboardEvent<HTMLDivElement>) {
    if (event.key === "Escape") {
      event.preventDefault()
      onRequestClose()
      return
    }
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault()
      if (!isDayDisabled(focusIso, bounds)) {
        onSelectDay(focusIso)
      }
      return
    }
    const move = moveCalendarFocus(
      focusIso,
      event.key,
      visibleMonth,
      weekStartsOn,
      bounds
    )
    if (move == null) return
    event.preventDefault()
    if (move.monthChanged) {
      onVisibleMonthChange(move.monthIso)
    }
    onFocusIsoChange(move.focusIso)
  }

  return (
    <div data-df="date-picker-panel">
      <div data-df="date-picker-header">
        <button
          type="button"
          data-df="date-picker-nav"
          aria-label={strings.datePickerPreviousMonth}
          onClick={() => goMonth(-1)}
        >
          <ChevronLeft aria-hidden />
        </button>
        <div data-df="date-picker-title" id={labelledBy}>
          {monthLabel}
        </div>
        <button
          type="button"
          data-df="date-picker-nav"
          aria-label={strings.datePickerNextMonth}
          onClick={() => goMonth(1)}
        >
          <ChevronRight aria-hidden />
        </button>
        <button
          type="button"
          data-df="date-picker-today"
          onClick={handleToday}
        >
          {strings.datePickerToday}
        </button>
      </div>

      <div
        role="grid"
        data-df="date-picker-grid"
        aria-labelledby={labelledBy}
        onKeyDown={handleGridKeyDown}
      >
        <div role="row" data-df="date-picker-weekdays">
          {weekdayLabels.map((label, index) => (
            <div
              key={`${label}-${index}`}
              role="columnheader"
              data-df="date-picker-weekday"
            >
              {label}
            </div>
          ))}
        </div>
        {Array.from({ length: 6 }, (_, week) => (
          <div key={week} role="row" data-df="date-picker-week">
            {cells.slice(week * 7, week * 7 + 7).map((cell) => {
              const state = classifyDay({
                iso: cell.date,
                inMonth: cell.inMonth,
                mode,
                value,
                draft,
                hover: hoverIso,
                min,
                max,
                disabledDates,
                today,
              })
              const isFocused = focusIso === cell.date
              return (
                <button
                  key={cell.date}
                  id={`${gridId}-${cell.date}`}
                  type="button"
                  role="gridcell"
                  data-df="date-picker-day"
                  data-outside={state.inMonth ? undefined : ""}
                  data-today={state.isToday ? "" : undefined}
                  data-selected={state.isSelected ? "" : undefined}
                  data-range-start={state.isRangeStart ? "" : undefined}
                  data-range-end={state.isRangeEnd ? "" : undefined}
                  data-in-range={state.isInRange ? "" : undefined}
                  data-preview={state.isPreview ? "" : undefined}
                  data-disabled={state.isDisabled ? "" : undefined}
                  aria-selected={state.isSelected || undefined}
                  aria-current={state.isToday ? "date" : undefined}
                  aria-disabled={state.isDisabled || undefined}
                  tabIndex={isFocused && !state.isDisabled ? 0 : -1}
                  disabled={state.isDisabled}
                  onMouseEnter={() => onHoverIsoChange(cell.date)}
                  onMouseLeave={() => onHoverIsoChange(null)}
                  onFocus={() => {
                    if (state.isDisabled) return
                    onFocusIsoChange(cell.date)
                  }}
                  onClick={() => {
                    if (state.isDisabled) return
                    onSelectDay(cell.date)
                  }}
                >
                  {Number.parseInt(cell.date.slice(8), 10)}
                </button>
              )
            })}
          </div>
        ))}
      </div>
    </div>
  )
}

function DatePicker({
  value: valueProp,
  defaultValue = null,
  onChange,
  min,
  max,
  disabledDates,
  placeholder,
  locale = "en-US",
  open,
  defaultOpen = false,
  onOpenChange,
  disabled,
  id,
  className,
  "aria-label": ariaLabel,
}: DatePickerProps) {
  const s = useDfStrings()
  const weekStartsOn = weekStartsOnForLocale(locale)
  const weekdayLabels = rotateWeekdayLabels(
    dfDatePickerWeekdays(s),
    weekStartsOn
  )
  const titleId = React.useId()
  const [isOpen, setOpen] = useControllableState({
    value: open,
    defaultValue: defaultOpen,
    onChange: onOpenChange,
  })
  const [value, setValue] = useControllableState<string | null>({
    value: valueProp,
    defaultValue,
    onChange,
  })
  const [visibleMonth, setVisibleMonth] = React.useState(() =>
    startOfUtcMonthIso(value ?? todayIsoDay())
  )
  const [focusIso, setFocusIso] = React.useState(
    () => value ?? todayIsoDay()
  )
  const [hoverIso, setHoverIso] = React.useState<string | null>(null)
  const [panelActive, setPanelActive] = React.useState(false)
  const bounds = React.useMemo<DayBounds>(
    () => ({ min, max, disabledDates }),
    [disabledDates, max, min]
  )

  if (isOpen && !panelActive) {
    setPanelActive(true)
    const seed = value ?? todayIsoDay()
    const focus = resolveNearestEnabledDay(seed, 1, bounds, {
      fallbackIso: resolveNearestEnabledDay(seed, -1, bounds, {
        fallbackIso: seed,
      }),
    })
    setVisibleMonth(startOfUtcMonthIso(focus))
    setFocusIso(focus)
    setHoverIso(null)
  } else if (!isOpen && panelActive) {
    setPanelActive(false)
  }

  function selectDay(iso: string) {
    if (isDayDisabled(iso, bounds)) return
    setValue(iso)
    setOpen(false)
  }

  return (
    <Popover open={isOpen} onOpenChange={setOpen}>
      <PopoverTrigger
        render={
          <Input
            id={id}
            readOnly
            disabled={disabled}
            value={value ?? ""}
            placeholder={placeholder ?? s.datePickerPlaceholder}
            trailingIcon={<CalendarIcon aria-hidden />}
            role="combobox"
            aria-haspopup="grid"
            aria-label={ariaLabel ?? s.datePickerAriaLabel}
            className={cn(className)}
          />
        }
      />
      <PopoverContent
        align="start"
        sideOffset={8}
        size="sm"
        className="df-date-picker-content"
      >
        <CalendarPanel
          mode="single"
          visibleMonth={visibleMonth}
          onVisibleMonthChange={setVisibleMonth}
          focusIso={focusIso}
          onFocusIsoChange={setFocusIso}
          value={value}
          hoverIso={hoverIso}
          onHoverIsoChange={setHoverIso}
          onSelectDay={selectDay}
          min={min}
          max={max}
          disabledDates={disabledDates}
          onRequestClose={() => setOpen(false)}
          labelledBy={titleId}
          locale={locale}
          weekStartsOn={weekStartsOn}
          weekdayLabels={weekdayLabels}
          strings={s}
        />
      </PopoverContent>
    </Popover>
  )
}

function DateRangePicker({
  value: valueProp,
  defaultValue = null,
  onChange,
  min,
  max,
  disabledDates,
  placeholder,
  locale = "en-US",
  open,
  defaultOpen = false,
  onOpenChange,
  disabled,
  id,
  className,
  "aria-label": ariaLabel,
}: DateRangePickerProps) {
  const s = useDfStrings()
  const weekStartsOn = weekStartsOnForLocale(locale)
  const weekdayLabels = rotateWeekdayLabels(
    dfDatePickerWeekdays(s),
    weekStartsOn
  )
  const titleId = React.useId()
  const [isOpen, setOpen] = useControllableState({
    value: open,
    defaultValue: defaultOpen,
    onChange: onOpenChange,
  })
  const [value, setValue] = useControllableState<DateRangeValue | null>({
    value: valueProp,
    defaultValue,
    onChange,
  })
  const [draft, setDraft] = React.useState<RangeDraft>(() =>
    draftFromValue(value)
  )
  const [visibleMonth, setVisibleMonth] = React.useState(() =>
    startOfUtcMonthIso(value?.start ?? todayIsoDay())
  )
  const [focusIso, setFocusIso] = React.useState(
    () => value?.start ?? todayIsoDay()
  )
  const [hoverIso, setHoverIso] = React.useState<string | null>(null)
  const [panelActive, setPanelActive] = React.useState(false)
  const bounds = React.useMemo<DayBounds>(
    () => ({ min, max, disabledDates }),
    [disabledDates, max, min]
  )

  if (isOpen && !panelActive) {
    setPanelActive(true)
    const seed = value?.start ?? todayIsoDay()
    const focus = resolveNearestEnabledDay(seed, 1, bounds, {
      fallbackIso: resolveNearestEnabledDay(seed, -1, bounds, {
        fallbackIso: seed,
      }),
    })
    setDraft(draftFromValue(value))
    setVisibleMonth(startOfUtcMonthIso(focus))
    setFocusIso(focus)
    setHoverIso(null)
  } else if (!isOpen && panelActive) {
    setPanelActive(false)
  }

  function selectDay(iso: string) {
    const next = applyBoundedRangeClick(draft, iso, bounds)
    if (next === draft) return
    setDraft(next)
    if (next.start != null && next.end != null) {
      setValue({ start: next.start, end: next.end })
      setOpen(false)
    }
  }

  return (
    <Popover open={isOpen} onOpenChange={setOpen}>
      <PopoverTrigger
        render={
          <Input
            id={id}
            readOnly
            disabled={disabled}
            value={formatRangeDisplay(value, s)}
            placeholder={placeholder ?? s.dateRangePickerPlaceholder}
            trailingIcon={<CalendarIcon aria-hidden />}
            role="combobox"
            aria-haspopup="grid"
            aria-label={ariaLabel ?? s.dateRangePickerAriaLabel}
            className={cn(className)}
          />
        }
      />
      <PopoverContent
        align="start"
        sideOffset={8}
        size="sm"
        className="df-date-picker-content"
      >
        <CalendarPanel
          mode="range"
          visibleMonth={visibleMonth}
          onVisibleMonthChange={setVisibleMonth}
          focusIso={focusIso}
          onFocusIsoChange={setFocusIso}
          draft={draft}
          hoverIso={hoverIso}
          onHoverIsoChange={setHoverIso}
          onSelectDay={selectDay}
          min={min}
          max={max}
          disabledDates={disabledDates}
          onRequestClose={() => setOpen(false)}
          labelledBy={titleId}
          locale={locale}
          weekStartsOn={weekStartsOn}
          weekdayLabels={weekdayLabels}
          strings={s}
        />
      </PopoverContent>
    </Popover>
  )
}

export { DatePicker, DateRangePicker }
export type { DatePickerProps, DateRangePickerProps, DateRangeValue }

import {
  addUtcDays,
  formatUtcDate,
  startOfUtcDay,
  toDate,
} from "../df-date/index"

export type CalendarCell = {
  date: string
  inMonth: boolean
  weekday: number
}

export type TimelineBar = {
  id: string
  /** Day offset from window start (0-based). */
  offsetDays: number
  /** Inclusive span in days. */
  spanDays: number
  /** Clipped when the bar starts before the window. */
  clippedStart: boolean
  /** Clipped when the bar ends after the window. */
  clippedEnd: boolean
}

export type GanttDependency = {
  fromId: string
  toId: string
}

/** Inclusive day count between two UTC dates (`yyyy-mm-dd` or Date). */
export function utcInclusiveDays(
  start: Date | string | number,
  end: Date | string | number
): number {
  const a = startOfUtcDay(start).getTime()
  const b = startOfUtcDay(end).getTime()
  if (b < a) throw new Error("End day must be on or after start day")
  return Math.floor((b - a) / 86_400_000) + 1
}

/** Day index of `date` relative to `windowStart` (may be negative). */
export function dayOffsetFrom(
  windowStart: Date | string | number,
  date: Date | string | number
): number {
  const a = startOfUtcDay(windowStart).getTime()
  const b = startOfUtcDay(date).getTime()
  return Math.floor((b - a) / 86_400_000)
}

/**
 * JS weekday for the first column of a week (0=Sunday through 6=Saturday)
 * from a BCP 47 locale.
 *
 * When the engine exposes no week info, this returns Sunday (0). That is a
 * degradation path for missing Intl data, not a claim that Sunday is the
 * intended default for every locale.
 */
export function weekStartsOnForLocale(locale: string): number {
  try {
    const loc = new Intl.Locale(locale)
    const withInfo = loc as Intl.Locale & {
      weekInfo?: { firstDay: number }
      getWeekInfo?: () => { firstDay: number }
    }
    const info =
      withInfo.weekInfo ??
      (typeof withInfo.getWeekInfo === "function"
        ? withInfo.getWeekInfo()
        : undefined)
    if (info?.firstDay == null) return 0
    return info.firstDay === 7 ? 0 : info.firstDay
  } catch {
    return 0
  }
}

/**
 * Offset of `weekday` (0=Sunday) from the first column of a week that starts
 * on `weekStartsOn`.
 */
export function offsetFromWeekStart(
  weekday: number,
  weekStartsOn: number
): number {
  return (weekday - weekStartsOn + 7) % 7
}

/**
 * Rotate Sunday-first weekday labels so index 0 matches `weekStartsOn`.
 */
export function rotateWeekdayLabels(
  sundayFirst: readonly [string, string, string, string, string, string, string],
  weekStartsOn: number
): readonly string[] {
  if (weekStartsOn === 0) return sundayFirst
  return [
    ...sundayFirst.slice(weekStartsOn),
    ...sundayFirst.slice(0, weekStartsOn),
  ]
}

/**
 * Build a month grid covering every day shown on the calendar surface for
 * `month` (`yyyy-mm` or any date in that month).
 *
 * `weekStartsOn` is required: the first column weekday (0=Sunday through
 * 6=Saturday). Callers must decide it from locale or an explicit policy;
 * this helper does not guess.
 */
export function buildMonthGrid(
  month: Date | string | number,
  weekStartsOn: number
): CalendarCell[] {
  const seed = startOfUtcDay(month)
  const year = seed.getUTCFullYear()
  const monthIndex = seed.getUTCMonth()
  const firstOfMonth = new Date(Date.UTC(year, monthIndex, 1))
  const startPad = offsetFromWeekStart(firstOfMonth.getUTCDay(), weekStartsOn)
  const gridStart = addUtcDays(firstOfMonth, -startPad)
  const cells: CalendarCell[] = []
  for (let i = 0; i < 42; i += 1) {
    const day = addUtcDays(gridStart, i)
    cells.push({
      date: formatUtcDate(day),
      inMonth: day.getUTCMonth() === monthIndex,
      weekday: day.getUTCDay(),
    })
  }
  return cells
}

/**
 * Project a subject span into a window as a bar. Returns null when the span
 * does not intersect the inclusive window.
 */
export function projectBar(input: {
  id: string
  startsOn: string
  endsOn: string
  windowStart: string
  windowEnd: string
}): TimelineBar | null {
  const start = startOfUtcDay(input.startsOn)
  const end = startOfUtcDay(input.endsOn)
  const winStart = startOfUtcDay(input.windowStart)
  const winEnd = startOfUtcDay(input.windowEnd)
  if (end.getTime() < winStart.getTime() || start.getTime() > winEnd.getTime()) {
    return null
  }
  const clippedStart = start.getTime() < winStart.getTime()
  const clippedEnd = end.getTime() > winEnd.getTime()
  const visibleStart = clippedStart ? winStart : start
  const visibleEnd = clippedEnd ? winEnd : end
  return {
    id: input.id,
    offsetDays: dayOffsetFrom(winStart, visibleStart),
    spanDays: utcInclusiveDays(visibleStart, visibleEnd),
    clippedStart,
    clippedEnd,
  }
}

/**
 * Assign lane indices so overlapping bars do not share a row.
 * Bars are sorted by offset then span.
 */
export function assignLanes(
  bars: readonly TimelineBar[]
): Array<TimelineBar & { lane: number }> {
  const sorted = bars.slice().sort((a, b) => {
    if (a.offsetDays !== b.offsetDays) return a.offsetDays - b.offsetDays
    return b.spanDays - a.spanDays
  })
  const laneEnds: number[] = []
  return sorted.map((bar) => {
    const barEnd = bar.offsetDays + bar.spanDays
    let lane = laneEnds.findIndex((end) => end <= bar.offsetDays)
    if (lane < 0) {
      lane = laneEnds.length
      laneEnds.push(barEnd)
    } else {
      laneEnds[lane] = barEnd
    }
    return { ...bar, lane }
  })
}

/** List UTC `yyyy-mm-dd` headers for a window (inclusive). */
export function windowDayHeaders(
  windowStart: Date | string | number,
  windowEnd: Date | string | number
): string[] {
  const start = startOfUtcDay(windowStart)
  const end = startOfUtcDay(windowEnd)
  const days = utcInclusiveDays(start, end)
  const headers: string[] = []
  for (let i = 0; i < days; i += 1) {
    headers.push(formatUtcDate(addUtcDays(start, i)))
  }
  return headers
}

/** Validate a dependency pair references known bar ids. */
export function filterDependencies(
  deps: readonly GanttDependency[],
  barIds: ReadonlySet<string>
): GanttDependency[] {
  return deps.filter(
    (dep) => barIds.has(dep.fromId) && barIds.has(dep.toId)
  )
}

export function parseYearMonth(value: string): Date {
  if (!/^\d{4}-\d{2}$/.test(value)) {
    throw new Error("Month must be yyyy-mm")
  }
  return toDate(`${value}-01T00:00:00.000Z`)
}

import { formatUtcDate, startOfUtcDay } from "../df-date/index"

import {
  isIsoInInclusiveRange,
  type DateRangeValue,
  type RangeDraft,
  resolveRangePreview,
} from "./range"
import {
  compareIsoDays,
  isDayDisabled,
  todayIsoDay,
} from "./month"

export type DayVisualState = {
  iso: string
  inMonth: boolean
  isToday: boolean
  isDisabled: boolean
  isSelected: boolean
  isRangeStart: boolean
  isRangeEnd: boolean
  isInRange: boolean
  isPreview: boolean
}

export type ClassifyDayInput = {
  iso: string
  inMonth: boolean
  mode: "single" | "range"
  value?: string | null | undefined
  rangeValue?: DateRangeValue | null | undefined
  draft?: RangeDraft | undefined
  hover?: string | null | undefined
  min?: string | null | undefined
  max?: string | null | undefined
  disabledDates?: ((dayIso: string) => boolean) | null | undefined
  today?: string | undefined
}

/** Classify a calendar day for selected, today, range, and disabled chrome. */
export function classifyDay(input: ClassifyDayInput): DayVisualState {
  const iso = formatUtcDate(startOfUtcDay(input.iso))
  const today = input.today ?? todayIsoDay()
  const isDisabled = isDayDisabled(iso, {
    min: input.min,
    max: input.max,
    disabledDates: input.disabledDates,
  })

  if (input.mode === "single") {
    return {
      iso,
      inMonth: input.inMonth,
      isToday: iso === today,
      isDisabled,
      isSelected: input.value != null && iso === input.value,
      isRangeStart: false,
      isRangeEnd: false,
      isInRange: false,
      isPreview: false,
    }
  }

  const draft = input.draft ?? {
    start: input.rangeValue?.start ?? null,
    end: input.rangeValue?.end ?? null,
  }
  const preview = resolveRangePreview(draft, input.hover ?? null)
  const committed =
    draft.start != null && draft.end != null
      ? { start: draft.start, end: draft.end }
      : input.rangeValue ?? null

  const active = preview ?? committed
  const isInRange =
    active != null && isIsoInInclusiveRange(iso, active.start, active.end)
  const isRangeStart = active != null && iso === active.start
  const isRangeEnd = active != null && iso === active.end
  const isPreview =
    draft.start != null &&
    draft.end == null &&
    preview != null &&
    isInRange

  return {
    iso,
    inMonth: input.inMonth,
    isToday: iso === today,
    isDisabled,
    isSelected: isRangeStart || isRangeEnd,
    isRangeStart,
    isRangeEnd,
    isInRange,
    isPreview,
  }
}

export function sameIsoDay(a: string | null | undefined, b: string): boolean {
  if (a == null) return false
  return compareIsoDays(a, b) === 0
}

import { addUtcDays, formatUtcDate, startOfUtcDay } from "../df-date/index"
import { offsetFromWeekStart } from "../df-calendar-grid/index"

import {
  compareIsoDays,
  monthKey,
  resolveNearestEnabledDay,
  shiftUtcMonth,
  startOfUtcMonthIso,
  type DayBounds,
} from "./month"

export type CalendarFocusMove = {
  focusIso: string
  /** True when the focused day leaves the prior visible month. */
  monthChanged: boolean
  monthIso: string
}

type MoveDirection = 1 | -1

function directionForKey(key: string): MoveDirection | null {
  switch (key) {
    case "ArrowLeft":
    case "ArrowUp":
    case "PageUp":
    case "Home":
      return -1
    case "ArrowRight":
    case "ArrowDown":
    case "PageDown":
    case "End":
      return 1
    default:
      return null
  }
}

function stayPut(focusIso: string, visibleMonthIso: string): CalendarFocusMove {
  return {
    focusIso: formatUtcDate(startOfUtcDay(focusIso)),
    monthChanged: false,
    monthIso: startOfUtcMonthIso(visibleMonthIso),
  }
}

function toMove(
  focusIso: string,
  resolvedIso: string,
  visibleMonthIso: string
): CalendarFocusMove {
  const focus = formatUtcDate(startOfUtcDay(focusIso))
  const resolved = formatUtcDate(startOfUtcDay(resolvedIso))
  if (compareIsoDays(focus, resolved) === 0) {
    return stayPut(focus, visibleMonthIso)
  }
  return {
    focusIso: resolved,
    monthChanged: monthKey(visibleMonthIso) !== monthKey(resolved),
    monthIso: startOfUtcMonthIso(resolved),
  }
}

/**
 * Move roving focus across a month grid.
 * Arrow keys step by day or week; Home/End bound the week for `weekStartsOn`
 * (0=Sunday through 6=Saturday; required, not guessed);
 * PageUp/PageDown shift the UTC month while preserving day of month.
 * Disabled and out of range days are skipped in the travel direction.
 */
export function moveCalendarFocus(
  focusIso: string,
  key: string,
  visibleMonthIso: string,
  weekStartsOn: number,
  bounds: DayBounds = {}
): CalendarFocusMove | null {
  const direction = directionForKey(key)
  if (direction == null) return null

  const focus = startOfUtcDay(focusIso)
  const focusDay = formatUtcDate(focus)
  let candidate: string
  let limitIso: string | undefined

  switch (key) {
    case "ArrowLeft":
      candidate = formatUtcDate(addUtcDays(focus, -1))
      break
    case "ArrowRight":
      candidate = formatUtcDate(addUtcDays(focus, 1))
      break
    case "ArrowUp":
      candidate = formatUtcDate(addUtcDays(focus, -7))
      break
    case "ArrowDown":
      candidate = formatUtcDate(addUtcDays(focus, 7))
      break
    case "Home": {
      const fromStart = offsetFromWeekStart(focus.getUTCDay(), weekStartsOn)
      candidate = formatUtcDate(addUtcDays(focus, -fromStart))
      limitIso = formatUtcDate(addUtcDays(focus, 6 - fromStart))
      break
    }
    case "End": {
      const fromStart = offsetFromWeekStart(focus.getUTCDay(), weekStartsOn)
      candidate = formatUtcDate(addUtcDays(focus, 6 - fromStart))
      limitIso = formatUtcDate(addUtcDays(focus, -fromStart))
      break
    }
    case "PageUp":
      candidate = formatUtcDate(shiftUtcMonth(focus, -1))
      break
    case "PageDown":
      candidate = formatUtcDate(shiftUtcMonth(focus, 1))
      break
    default:
      return null
  }

  const searchDirection: MoveDirection =
    key === "Home" ? 1 : key === "End" ? -1 : direction

  const resolved = resolveNearestEnabledDay(candidate, searchDirection, bounds, {
    limitIso,
    fallbackIso: focusDay,
  })

  return toMove(focusDay, resolved, visibleMonthIso)
}

import {
  addUtcDays,
  formatUtcDate,
  startOfUtcDay,
  toDate,
} from "../df-date/index"

export type DayBounds = {
  min?: string | null | undefined
  max?: string | null | undefined
  disabledDates?: ((dayIso: string) => boolean) | null | undefined
}

/** Shift a UTC calendar month, clamping the day into the target month. */
export function shiftUtcMonth(
  value: Date | string | number,
  months: number
): Date {
  const seed = startOfUtcDay(value)
  const target = new Date(
    Date.UTC(seed.getUTCFullYear(), seed.getUTCMonth() + months, 1)
  )
  const year = target.getUTCFullYear()
  const month = target.getUTCMonth()
  const daysInMonth = new Date(Date.UTC(year, month + 1, 0)).getUTCDate()
  const day = Math.min(seed.getUTCDate(), daysInMonth)
  return new Date(Date.UTC(year, month, day))
}

/** `yyyy-mm` key for the UTC month containing `value`. */
export function monthKey(value: Date | string | number): string {
  const date = startOfUtcDay(value)
  const year = date.getUTCFullYear()
  const month = String(date.getUTCMonth() + 1).padStart(2, "0")
  return `${year}-${month}`
}

/** First day of the UTC month for `value` as `yyyy-mm-dd`. */
export function startOfUtcMonthIso(value: Date | string | number): string {
  const date = startOfUtcDay(value)
  return formatUtcDate(
    new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), 1))
  )
}

/** Locale month label for a UTC month (`July 2026`). */
export function formatUtcMonthLabel(
  value: Date | string | number,
  locale = "en-US"
): string {
  const date = startOfUtcDay(value)
  return new Intl.DateTimeFormat(locale, {
    month: "long",
    year: "numeric",
    timeZone: "UTC",
  }).format(date)
}

/** Compare two ISO day strings (`yyyy-mm-dd`). */
export function compareIsoDays(a: string, b: string): number {
  if (a === b) return 0
  return a < b ? -1 : 1
}

/** Clamp an ISO day into an optional inclusive `[min, max]` window. */
export function clampIsoDay(
  iso: string,
  min?: string | null,
  max?: string | null
): string {
  let next = formatUtcDate(startOfUtcDay(iso))
  if (min != null && compareIsoDays(next, min) < 0) next = min
  if (max != null && compareIsoDays(next, max) > 0) next = max
  return next
}

/** True when `iso` falls outside optional min/max or a custom predicate. */
export function isDayDisabled(
  iso: string,
  options: DayBounds = {}
): boolean {
  const day = formatUtcDate(startOfUtcDay(iso))
  if (options.min != null && compareIsoDays(day, options.min) < 0) return true
  if (options.max != null && compareIsoDays(day, options.max) > 0) return true
  if (options.disabledDates?.(day)) return true
  return false
}

/**
 * Clamp `candidateIso` into min/max, then walk in `direction` until an
 * enabled day is found. Returns `fallbackIso` when none exists in range.
 */
export function resolveNearestEnabledDay(
  candidateIso: string,
  direction: 1 | -1,
  bounds: DayBounds = {},
  options: {
    limitIso?: string | undefined
    fallbackIso?: string | undefined
  } = {}
): string {
  const fallback =
    options.fallbackIso ?? formatUtcDate(startOfUtcDay(candidateIso))
  let day = clampIsoDay(candidateIso, bounds.min, bounds.max)

  for (let step = 0; step < 400; step += 1) {
    if (options.limitIso != null) {
      if (direction === 1 && compareIsoDays(day, options.limitIso) > 0) {
        return fallback
      }
      if (direction === -1 && compareIsoDays(day, options.limitIso) < 0) {
        return fallback
      }
    }
    if (!isDayDisabled(day, bounds)) return day

    const next = formatUtcDate(addUtcDays(day, direction))
    if (bounds.min != null && compareIsoDays(next, bounds.min) < 0) {
      return fallback
    }
    if (bounds.max != null && compareIsoDays(next, bounds.max) > 0) {
      return fallback
    }
    if (options.limitIso != null) {
      if (direction === 1 && compareIsoDays(next, options.limitIso) > 0) {
        return fallback
      }
      if (direction === -1 && compareIsoDays(next, options.limitIso) < 0) {
        return fallback
      }
    }
    day = next
  }

  return fallback
}

/** Today as a UTC ISO day string. */
export function todayIsoDay(now: Date | string | number = Date.now()): string {
  return formatUtcDate(startOfUtcDay(toDate(now)))
}

import { compareIsoDays, isDayDisabled, type DayBounds } from "./month"

export type DateRangeValue = {
  start: string
  end: string
}

export type RangeDraft = {
  start: string | null
  end: string | null
}

/**
 * Apply a day click to a range draft.
 * A complete range or empty draft starts a new selection.
 * Clicking before the start while choosing the end restarts at the click.
 */
export function applyRangeClick(
  draft: RangeDraft,
  clicked: string
): RangeDraft {
  if (draft.start == null || draft.end != null) {
    return { start: clicked, end: null }
  }
  if (compareIsoDays(clicked, draft.start) < 0) {
    return { start: clicked, end: null }
  }
  return { start: draft.start, end: clicked }
}

/**
 * Same as pointer clicks: reject out of range and disabled days without
 * mutating the draft.
 */
export function applyBoundedRangeClick(
  draft: RangeDraft,
  clicked: string,
  bounds: DayBounds = {}
): RangeDraft {
  if (isDayDisabled(clicked, bounds)) return draft
  return applyRangeClick(draft, clicked)
}

/** Resolve the inclusive highlight span for a draft plus optional hover. */
export function resolveRangePreview(
  draft: RangeDraft,
  hover: string | null
): DateRangeValue | null {
  if (draft.start == null) return null
  if (draft.end != null) {
    return orderRange(draft.start, draft.end)
  }
  if (hover == null) {
    return { start: draft.start, end: draft.start }
  }
  return orderRange(draft.start, hover)
}

export function orderRange(a: string, b: string): DateRangeValue {
  return compareIsoDays(a, b) <= 0
    ? { start: a, end: b }
    : { start: b, end: a }
}

export function isIsoInInclusiveRange(
  iso: string,
  start: string,
  end: string
): boolean {
  const range = orderRange(start, end)
  return (
    compareIsoDays(iso, range.start) >= 0 &&
    compareIsoDays(iso, range.end) <= 0
  )
}

/** Convert a committed value into a draft used while the panel is open. */
export function draftFromValue(
  value: DateRangeValue | null | undefined
): RangeDraft {
  if (value == null) return { start: null, end: null }
  return { start: value.start, end: value.end }
}

/** Owned date helpers. Prefer UTC day boundaries unless a timezone is supplied. */

export function toDate(value: Date | string | number): Date {
  const date = value instanceof Date ? new Date(value.getTime()) : new Date(value)
  if (Number.isNaN(date.getTime())) {
    throw new Error("Invalid date")
  }
  return date
}

export function startOfUtcDay(value: Date | string | number): Date {
  const date = toDate(value)
  return new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate()))
}

export function addUtcDays(value: Date | string | number, days: number): Date {
  const date = toDate(value)
  date.setUTCDate(date.getUTCDate() + days)
  return date
}

export function formatUtcDate(
  value: Date | string | number,
  pattern: "yyyy-mm-dd" | "iso" = "yyyy-mm-dd"
): string {
  const date = toDate(value)
  if (pattern === "iso") return date.toISOString()
  const year = date.getUTCFullYear()
  const month = String(date.getUTCMonth() + 1).padStart(2, "0")
  const day = String(date.getUTCDate()).padStart(2, "0")
  return `${year}-${month}-${day}`
}

export function utcDayRange(
  start: Date | string | number,
  end: Date | string | number
): { start: Date; end: Date } {
  const startDay = startOfUtcDay(start)
  const endDay = startOfUtcDay(end)
  if (endDay.getTime() < startDay.getTime()) {
    throw new Error("End day must be on or after start day")
  }
  return { start: startDay, end: endDay }
}
